"""Build the plain static verification website; Python 3, no dependencies."""
from pathlib import Path
from html import escape
import shutil

root = Path(__file__).resolve().parent
out = root / 'public'
out.mkdir(exist_ok=True)
nav = [('Home','/'),('Download','/download'),('Plus','/plus'),('Privacy','/privacy'),('Help','/help'),('Terms','/terms'),('Delete account','/delete-account')]
email = '<!--email_off--><a href="mailto:support@oftenenough.com">support@oftenenough.com</a><!--/email_off-->'
def section(title, body):
    return f'<section><h2>{title}</h2>{body}</section>'
def card(title, body):
    return f'<section class="card"><h2>{title}</h2>{body}</section>'

pages = {}
pages['index'] = ('A habit tracker for your real life', '''<section class="hero"><p class="eyebrow">OFTEN ENOUGH</p><h1>A habit tracker<br>for your real life.</h1><p class="lead">Build habits, follow routines, and see your progress at your own pace.</p><p><a class="button" href="/download">Apps and availability</a> <a href="/plus">Explore Plus →</a></p><p class="muted">Preparing for release. Public download links are not available yet.</p></section><section id="features"><h2>Your habits. Your way.</h2><p>Choose goals that fit your life: daily, weekly or monthly.</p><div class="grid">'''+card('📅 Flexible goals','<p>Checks, amounts, time and checklist steps. Set a schedule that works for you.</p>')+card('🌱 Quit or cut down','<p>Track time since stopping, or set a maximum amount or time limit.</p>')+card('⏱️ Guided routines','<p>Follow a morning routine one step at a time, with timers when you need them.</p>')+card('📊 Visible progress','<p>See how small actions add up over weeks, months and years.</p>')+card('📱 Interactive widgets','<p>Check off habits, add an amount or control a timer from supported widgets.</p>')+card('✓ Tasks, too','<p>Keep one-time tasks alongside the things you do regularly.</p>')+'''</div></section><section class="callout"><h2>Your habits stay yours.</h2><p>Your records live on your devices and, when enabled, in your own cloud. We do not operate a server that stores your habit records.</p><a href="/privacy">Read the privacy policy →</a></section><section id="devices"><h2>Made for the devices you use.</h2><p>iPhone, iPad and Apple Watch are being prepared for release. Android phone is in development; Wear OS, Android tablet and desktop apps are planned. See <a href="/download">Download</a> for availability.</p></section>''')
pages['download'] = ('Download', '''<p class="eyebrow">FIND YOUR DEVICE</p><h1>A little habit.<br>Wherever you are.</h1><p class="lead">Often Enough is in development. Official store links will appear here when the apps are publicly available.</p><div class="grid">'''+card('Apple','<p><strong>iPhone · iPad · Apple Watch</strong></p><p>Preparing for release, with your own iCloud for supported backup and sync.</p><p class="status">App Store link coming soon</p>')+card('Android','<p><strong>Phone in development</strong></p><p>Built around the same core habit features and your own Google Drive. Wear OS and Android tablet are planned later.</p><p class="status">Google Play link coming soon</p>')+card('Desktop','<p><strong>Planned</strong></p><p>Supported operating systems, requirements and release dates will be announced here.</p><p class="status">Downloads not available yet</p>')+'''</div><section><h2>Use the official store links.</h2><p>This is the official development website. It does not currently offer installers, a waitlist, checkout or sign-in. No download or payment is required for website verification.</p><a href="/help">Get help →</a></section>''')
pages['plus'] = ('Plus', '''<p class="eyebrow">MORE ROOM, WHEN YOU WANT IT</p><h1>Start free.<br>Keep building.</h1><p class="lead">Begin with five active habits. Plus adds more room with one purchase.</p><div class="grid">'''+card('Free','<p class="status">A real place to start</p><ul><li>Up to five active habits</li><li>Track habits and tasks</li><li>Export and restore your records</li><li>Personal-cloud backup and supported free sync behavior</li></ul>')+card('Plus','<p class="status">One-time purchase</p><ul><li>Unlimited habits</li><li>Supported additional-device features on iPad and Apple Watch</li><li>Sync supported Apple devices through your own iCloud</li></ul>')+card('Plus Family','<p class="status">For your Apple family</p><p>Plus benefits for you and up to five other members of your Apple Family Sharing group. Each person keeps their own habit records private.</p>')+'''</div><section><h2>One-time. No subscription.</h2><p>Buy Plus inside the app after release. The store shows the current price for your country and the included features before you confirm. This website does not take payments.</p><p>Use <strong>Restore Purchases</strong> with the store account used for your purchase. Refunds and Family Sharing follow the store's rules.</p><p>Android pricing, cross-store entitlements and family options will be confirmed before Android release. An Apple purchase does not currently unlock an unreleased Android app.</p><a class="button" href="/download">Check availability</a></section>''')
pages['privacy'] = ('Privacy policy', '''<p class="eyebrow">YOUR HABITS STAY YOURS</p><h1>Privacy policy</h1><p class="muted">Updated 15 October 2026 · Pre-release verification version</p><p>This policy covers the Often Enough app under development and this website. Privacy enquiries: '''+email+'''.</p>'''+section('The short version','<ul><li>Your habits, tasks, logs, notes and goals are stored on your devices. We do not run a server that receives or stores these records.</li><li>Backup and sync, when enabled, use your own cloud.</li><li>Signing in with Google or Apple is optional. An optional account keeps Plus, family membership and which cloud you use, never your habits. The account service is being prepared.</li><li>We do not sell personal information or use advertising trackers.</li><li>Optional usage sharing is separate from habit records. This website contains no analytics or advertising scripts.</li></ul>')+section('Your records and your cloud','<p>The local database lets you log habits offline. Supported Apple builds use your private iCloud database for sync and separate files in iCloud Drive for dated backups. We cannot browse those private habit records. Apple processes them under its own terms and privacy policy.</p><p>Google Drive backup and Android sync are being prepared. They require your explicit Google permission when available. The current iPhone build keeps the Drive option disabled pending configuration. A connection is for the app’s own data, rather than general access to your documents.</p><p>iCloud and Google Drive do not automatically sync with one another. Export and Import move a copy between platforms. Exported or shared files go to the destination you choose.</p>')+section('Your optional account','<p>Signing in is optional, using Google or Apple only. The app works fully without an Often Enough account.</p><p>The account service is being prepared and is not live in the current release build. When available, if you create an account, we keep only:</p><ul><li>An account ID and the identifier of the Google or Apple account you signed in with.</li><li>A shortened form of your email, such as <code>l•••••@gmail.com</code>, never your full email.</li><li>Your Plus purchase: product, store and date, checked with Google or Apple, and refunds.</li><li>Who is in your family, if you use Plus Family.</li><li>Which cloud holds your habits (iCloud or Google Drive), that cloud account’s private ID, and when a device last synced.</li></ul><p><strong>Never your habits, tasks, logs or notes.</strong> They stay on your devices and in your own iCloud or Google Drive.</p><p>We use these account details to keep Plus and your family on all your devices and both stores, and to point you back to the right cloud. Providing them is optional; they are used for account management and Plus functionality.</p><p>The account server is a Cloudflare Worker. Cloudflare processes these account details on our behalf to run the service. They are encrypted in transit.</p><p><strong>Plus &amp; Account › Delete my account</strong> removes your account and, if you own a family, the family too. Purchases stay with Google or Apple, so signing in again brings Plus back. Deleting this account does not delete your habit records: see <a href="/delete-account">Delete account and data</a> for the separate controls.</p>')+section('Optional usage sharing','<p>Where offered, <strong>Privacy &amp; Security → Share Usage</strong> controls feature counts and estimated active screen time, associated with a random installation identifier. Eligible production delivery uses PostHog’s EU endpoint. App/build version, OS major version and release-channel information can accompany events.</p><p>Habit and task names, notes, goals, logged values, account details and advertising identifiers are excluded. Turning sharing off stops collection, clears pending usage data and rotates the local analytics identity. Queued records expire after seven days. This data is not used for cross-app advertising.</p><p>Production delivery is gated separately from consent. The production configuration and provider retention will be reviewed and published before public collection is enabled. Crash sharing is not available in the current build; we do not claim a crash-reporting service is active.</p>')+section('Purchases and device permissions','<p>Apple or Google processes store purchases and payment details. The app reads entitlements to unlock Plus and restore purchases. We do not receive your full card details. Stores may retain transaction records for legal obligations.</p><p>Notifications and supported integrations use permissions you grant on your device. They do not grant us access to unrelated photos, contacts, recordings or location. Change permissions in system settings.</p>')+section('This website and support','<p>Cloudflare hosts this website and may process IP address, requested URL, request time, browser headers and security information to deliver and protect it. Cloudflare may use essential security cookies. The static site does not create accounts, take payments, upload habit data or set its own analytics cookies.</p><p>Support receives your email address and information you choose to send. Avoid sensitive habit details unless needed. Correspondence is used to answer your request and kept only as long as needed for support, security or legal obligations. Ask us to remove it when no longer needed.</p>')+section('Retention, export and deletion','<p>Local records remain until you erase them or delete the app. Your own cloud retains records and rotating backups according to app settings and provider storage rules. Exported copies remain where you saved them until you delete them there.</p><p>Use <strong>Save a Backup File</strong> or <strong>Export a Spreadsheet (CSV)</strong> in the app. Local erasure and cloud deletion are separate: see <a href="/delete-account">Delete account and data</a>. Deleting the app alone does not remove cloud backups.</p><p>We cannot remotely retrieve or erase private records on your device or in your own cloud. Contact us about information we hold, such as support correspondence or optional usage data. Depending on local law, you may have rights to access, correction, deletion, restriction, objection, portability, withdrawal of consent and a complaint to your data-protection authority. A request may require proportionate verification.</p>')+section('Children and policy changes','<p>Often Enough is not directed to children under 13. Where local law requires parental consent at a higher age, that requirement applies. Contact us if you believe a child has sent us personal information.</p><p>We will update this policy to reflect actual services, including before public release, and communicate material changes where required.</p><p>Provider policies: <a href="https://www.apple.com/legal/privacy/">Apple</a>, <a href="https://policies.google.com/privacy">Google</a>, <a href="https://www.cloudflare.com/privacypolicy/">Cloudflare</a>, <a href="https://posthog.com/privacy">PostHog</a>.</p>'))
pages['help'] = ('Help', '''<p class="eyebrow">A LITTLE HELP</p><h1>Keep going.<br>We are here to help.</h1><p class="lead">Guidance for the app under development. Available features and menu names may vary by platform or build.</p>'''+section('Getting started','<p>Create a habit, choose its schedule and set a goal using checks, amounts, time or checklist steps. Weekly and monthly goals do not require the same amount every day.</p>')+section('Logging and routines','<p>Use the habit’s check or amount control to log an action. Timers track duration; checklists track steps. Guided routines take you through habits one at a time. The named Undo action corrects the most recent entry.</p>')+section('Widgets and reminders','<p>Add Often Enough from the system widget gallery, then use Edit Widget to choose a habit or section. Checks, saved increments and timers act directly on supported Home Screen widgets; actions needing more information open the app. Lock Screen families have different capabilities.</p><p>Use <strong>Privacy &amp; Security → Hide Names Outside the App</strong> to hide names in widgets and reminders. Manage notification permission in device settings.</p>')+section('Backup and moving devices','<p>Check the app’s <strong>iCloud &amp; Backup</strong> page for cloud status. Use <strong>Save a Backup File</strong> before moving or deleting the app. Save outside Often Enough’s own folder. CSV export is for reading history; use a backup file for restoring.</p><p>Use <strong>Restore From a Backup</strong> or <strong>Import a Backup File</strong> on the destination device and review its preview. iCloud recovery requires the correct Apple Account and cloud settings. Storage, permissions and connectivity affect backup and sync. Google Drive and Android support are being prepared.</p>')+section('Plus and purchases','<p>Start with five active habits. Plus is a one-time in-app purchase. Use <strong>Restore Purchases</strong> with the same store account if your purchase is missing. Refund requests go to the store. See <a href="/plus">Plus</a>.</p>')+section('Account and data removal','<p>The current Apple architecture has no separate Often Enough habit account. Device records, cloud copies and store purchases have separate controls. See <a href="/delete-account">data-removal instructions</a>.</p>')+section('Still need a hand?','<p>Write to '+email+'. Include your device, OS, app version and what happened. Send screenshots or habit details only if you choose to. We do not need your password or card details.</p>'))
pages['terms'] = ('Terms of use', '''<p class="eyebrow">THE SMALL PRINT</p><h1>Terms of use</h1><p class="muted">Updated 15 October 2026 · Pre-release verification version</p><p>These terms cover the Often Enough app and website. By using them, you agree to these terms and applicable store terms. Questions: '''+email+'''.</p>'''+section('Development and availability','<p>Often Enough is under active development. This site supplies product, support and policy information for verification. A planned platform or feature is not a promise of a release date. Public apps and purchases will be available only through announced official store links.</p>')+section('Using the app','<p>Use Often Enough for lawful personal habit, task and routine tracking under the license supplied with your download. Do not circumvent security, misuse the service, infringe others’ rights or distribute malicious content. The app does not provide medical advice, diagnosis or treatment. You remain responsible for decisions based on your records.</p>')+section('Free, Plus and purchases','<p>The free plan supports five active habits. Plus and Plus Family are planned as one-time purchases, not subscriptions. The store shows localized pricing, eligibility and included features before confirmation. Family Sharing follows Apple’s rules; Android offerings will be confirmed separately.</p><p>The store processes payment, taxes, restoration and refunds. Refunded or revoked entitlements may end Plus features; existing records remain yours. This website does not take payments.</p>')+section('Your data and third-party services','<p>You retain rights to your records. They live on your devices and in your own cloud when enabled. Read the <a href="/privacy">privacy policy</a> for data flows and optional usage sharing. Keep a backup outside the app before deleting it or replacing your device. Review restore and deletion confirmations carefully.</p><p>Apple, Google, Cloudflare and disclosed providers have their own terms, storage limits and service availability. We do not guarantee automatic transfer between different clouds or stores.</p>')+section('Availability and consumer rights','<p>We work to keep the app reliable, but cannot guarantee uninterrupted operation or error-free development builds. To the extent allowed by law, the app and site are provided as available without additional warranties. Nothing here excludes mandatory consumer rights, liabilities that cannot legally be excluded, or applicable store refund rights.</p><p>We may change development features and update these terms. The date above identifies the current version; material changes will be communicated where required. Stop using the app if you do not agree to an applicable change.</p>')+section('Contact','<p>Product and terms enquiries: '+email+'. Store-specific seller information and any additional terms appear in the official listing when available.</p>'))
pages['delete-account'] = ('Delete account and data', '''<p class="eyebrow">YOU ARE IN CONTROL</p><h1>Delete your account<br>and data.</h1><p class="lead">An Often Enough account is optional; the app works fully without one. Account details, device records, private-cloud copies and store purchases have separate removal controls.</p><section class="callout"><h2>Before deleting anything</h2><p>Use <strong>iCloud &amp; Backup → Save a Backup File</strong> or <strong>Export a Spreadsheet (CSV)</strong> if you want a copy. Save outside the app’s own folder. Read each confirmation; deletion can be permanent.</p></section>'''+section('Delete your optional account','<p>The optional account service is being prepared and is not live in the current release build. When available, open <strong>Plus &amp; Account › Delete my account</strong> in the app and review the confirmation.</p><p>This removes your account, including its sign-in identifiers, shortened email, purchase/refund details, family membership and cloud-location details. If you own a Plus Family, it removes the family too.</p><p>Your purchases stay with Google or Apple, so signing in again brings Plus back. Deleting your Often Enough account does not delete your Google or Apple account, cancel a store purchase or request a refund.</p><p>Your habits, tasks, logs and notes are never in this account. They remain on your devices and in your own iCloud or Google Drive. Use the separate controls below to remove those records.</p>')+section('1. Remove this device’s records','<p>Open Often Enough → menu → <strong>iCloud &amp; Backup → Erase All My Data</strong>, then review and confirm. This clears local records and local recovery copies on this device, not your private-cloud or exported copies.</p><p>Deleting the app also removes local app data, but does not remove iCloud data. Offload App on iPhone keeps documents and data.</p>')+section('2. Remove Often Enough data from iCloud','<p>Open <strong>iCloud &amp; Backup → Delete My Data From iCloud</strong>. This removes the app’s synced records and backup files in your iCloud while keeping records on this device. Cloud sending stays off until you deliberately enable it again. Use both controls to remove local and cloud data.</p><p>You can also review app storage in Apple’s iCloud settings. We cannot perform private-cloud deletion remotely. Other devices and exported files may still hold copies; review them separately.</p>')+section('3. Google Drive and exported files','<p>If you used a build with Drive backup enabled, disconnect Often Enough in your Google Account and use Google Drive’s app-management controls to delete hidden app data where offered. Revoking permission alone does not necessarily delete stored copies.</p><p>Remove backups from Files, Drive, email attachments, device backups and other places you saved them. Android is in development; Android-specific in-app instructions will be published before release.</p>')+section('4. Purchases and usage data','<p>Erasing app records does not delete your Apple or Google account or the store’s purchase history. A one-time Plus purchase has no subscription to cancel. Ask the store about refunds.</p><p>Turn off <strong>Privacy &amp; Security → Share Usage</strong> to stop optional collection and clear pending events. Contact '+email+' about support messages or usage information already received. We may need proportionate details to verify a request about data we hold. Never send your password.</p>')+section('Need help without the app?','<p>Email '+email+' with the subject “Often Enough data deletion”. We can help you find the correct controls and handle support correspondence. This static website cannot sign into your device or cloud and does not claim to complete deletion online.</p><p>For help deleting your optional Often Enough account, include your app version and build number so support can identify the available controls. The account service never holds your habits, tasks, logs or notes.</p><a href="/privacy">Read the privacy policy →</a>'))

for slug,(title,body) in pages.items():
    path = '/' if slug == 'index' else '/' + slug
    links = ''.join(f'<a href="{url}"'+(' aria-current="page"' if url==path else '')+f'>{label}</a>' for label,url in nav)
    html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · Often Enough</title><meta name="description" content="{escape(title,quote=True)} — Often Enough development and verification website."><link rel="canonical" href="https://oftenenough.com{path}"><link rel="stylesheet" href="/style.css"><link rel="icon" href="/favicon.svg" type="image/svg+xml"></head><body><a class="skip" href="#main">Skip to content</a><div class="notice"><strong>Work in progress</strong> · Often Enough is under development. This is a verification website; apps and downloads are not publicly released.</div><header><a class="brand" href="/"><img src="/favicon.svg" width="38" height="38" alt="">Often Enough</a><nav aria-label="Main navigation">{links}</nav></header><main id="main">{body}</main><footer><p><strong>Often Enough</strong> · Small actions, repeated often enough.</p><nav aria-label="Footer navigation">{links}</nav><p>{email}</p><p class="muted">© 2026 Often Enough · Website and app development are ongoing.</p></footer></body></html>'''
    (out/(slug+'.html')).write_text(html,encoding='utf-8')
shutil.copyfile(out/'help.html',out/'support.html')
shutil.copyfile(root.parent/'Brand/Assets/BrandMarks/Light Tonal.svg',out/'favicon.svg')
(out/'404.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found · Often Enough</title><link rel="stylesheet" href="/style.css"></head><body><main><p class="eyebrow">OFTEN ENOUGH · WORK IN PROGRESS</p><h1>Page not found.</h1><p>This page may have moved while we build the website.</p><p><a class="button" href="/">Go home</a> <a href="/help">Get help</a></p></main></body></html>',encoding='utf-8')
(out/'_headers').write_text("/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Frame-Options: DENY\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n  Content-Security-Policy: default-src 'self'; script-src 'none'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'\n",encoding='utf-8')
(out/'_redirects').write_text('/support /help 301\n/privacy-policy /privacy 301\n/terms-and-conditions /terms 301\n',encoding='utf-8')
(out/'style.css').write_text('''
:root{color-scheme:light;--ink:#181818;--muted:#585858;--line:#dedede;--panel:#f4f4f2;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink);background:#fff}*{box-sizing:border-box}body{margin:0;font-size:17px;line-height:1.65}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}a:focus-visible{outline:3px solid #555;outline-offset:5px}p{margin:0 0 1.1em}h1,h2{line-height:1.13;letter-spacing:-.035em;overflow-wrap:break-word}h1{font-size:clamp(2.7rem,6vw,4.8rem);margin:.3em 0 .4em;font-weight:750}h2{font-size:clamp(1.5rem,3vw,2rem);margin:0 0 .65em}ul,ol{padding-left:1.3em}li{margin-bottom:.5em}header,main,footer{width:min(1080px,calc(100% - 48px));margin-inline:auto}header{padding:25px 0;display:flex;align-items:center;justify-content:space-between;gap:24px;border-bottom:1px solid var(--line)}.brand{font-size:20px;font-weight:700;display:flex;align-items:center;gap:10px;flex-shrink:0;text-decoration:none}.brand img{display:block}nav{display:flex;flex-wrap:wrap;gap:10px 22px}nav a{font-size:14px;text-decoration:none;min-height:36px;display:flex;align-items:center}nav a[aria-current]{font-weight:750;text-decoration:underline}main{padding:64px 0 48px;min-height:65vh}main>section{margin:0 0 48px}main>p,main>section:not(.hero):not(#features){max-width:850px}.notice{padding:12px 24px;background:#eee;color:#383838;text-align:center;font-size:13px;line-height:1.6}.eyebrow{font-size:12px;letter-spacing:.15em;font-weight:700;color:var(--muted);margin-bottom:20px}.lead{font-size:clamp(1.2rem,2.6vw,1.45rem);color:var(--muted);max-width:720px;line-height:1.55}.hero{padding:24px 0 44px}.muted{color:var(--muted);font-size:.9em}.button{display:inline-flex;align-items:center;justify-content:center;background:var(--ink);color:white;border:1px solid var(--ink);padding:12px 22px;border-radius:30px;text-decoration:none;min-height:48px;font-weight:600;font-size:15px;margin:8px 14px 8px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:25px 0 48px}.card{border:1px solid var(--line);border-radius:20px;padding:25px;margin:0;background:#fff;min-width:0}.card h2{font-size:22px}.card p,.card li{font-size:16px}.card p:last-child{margin-bottom:0}.callout{padding:32px;border-radius:24px;background:var(--panel)}.status{font-weight:650;color:#484848;font-size:14px}footer{border-top:1px solid var(--line);padding:32px 0 40px;font-size:14px}footer nav{margin:20px 0}.skip{position:absolute;left:16px;top:-90px;background:white;padding:12px;z-index:2}.skip:focus{top:10px}a,p,li{overflow-wrap:anywhere}@media(max-width:850px){header{align-items:flex-start;flex-direction:column;gap:14px}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}main{padding-top:44px}}@media(max-width:540px){header,main,footer{width:calc(100% - 36px)}header{padding-top:20px}.notice{padding:10px 18px;font-size:12px}nav{gap:5px 17px}nav a{font-size:13px;min-height:40px}.grid{grid-template-columns:1fr;gap:14px}.card{padding:23px}.callout{padding:24px}.hero{padding:6px 0 20px}main>section{margin-bottom:36px}h1{font-size:2.65rem}}
''',encoding='utf-8')
print('Wrote seven verification pages, support compatibility, 404, headers, redirects, CSS and approved brand asset.')
